/// Read the cached content and verify integrity.
///
/// If the entry has a content hash, the read content is verified against
/// it. A mismatch indicates concurrent writer corruption — the caller
/// should treat this as a cache miss and re-fetch.
pub fn read_content(&self, entry: &CacheEntry) -> Result<String> {
    let content = fs::read_to_string(&entry.content_path).with_context(|| {
        format!(
            "Failed to read cached content from {:?}",
            entry.content_path
        )
    })?;

    if let Some(expected_hash) = &entry.metadata.content_hash {
        let actual_hash = hex::encode(&Sha256::digest(content.as_bytes())[..16]);
        if actual_hash != *expected_hash {
            bail!(
                "Cache integrity check failed for {:?}: content was modified by another process",
                entry.content_path
            );
        }
    }

    Ok(content)
}

